#!/usr/bin/env node
const program = require('commander');
let fs = require("fs");

const { spawn ,fork } = require("child_process");
const path = require("path");
//console.log("compile_qc ####################################!");
program
    .option("-w, --workspace <workspacePath>", "Incoming workspace path")
    .parse(process.argv);


let cwd = process.cwd();
// "D:\\jjq\\game\\tools\\qatools\\npm\\node_modules\\layaair2-cmd"

// let projPath = program.workspace ? program.workspace : process.cwd();

let work = program.workspace;
let cs = path.join(cwd, "script", 'compile.js');
let s = fs.readFileSync(cs,{encoding:"utf8"});

let prefixName = path.dirname(work).split('\\').pop();

s = s.replace('your workspace path',work.replace(/\\/g,'/'));

let filename =  `compile_${prefixName}.js`;
// `compile${Date.now()}.js`


let gulpFilePath = path.join(cwd, "script", filename);
fs.writeFileSync(gulpFilePath,s,{encoding:"utf8"});

// let gulpFilePath = path.join(projPath, ".laya", "compile.js");

let gulpDir = path.join(process.argv[1],"../node_modules","gulp/bin/gulp.js");

let cmd = [`--gulpfile=${gulpFilePath}`, "compile"];

console.log(cmd);

let _gulp = fork(gulpDir, cmd, {
    silent: true,
    shell: true
});

_gulp.stdout.on('data', (data) => {
    console.log(`${data}`);
});
  
_gulp.stderr.on('data', (data) => {
    console.log(`${data}`);
});

_gulp.on('close', (code) => {
    console.log(`exit：${code}`);
    // fs.unlinkSync(gulpFilePath);
});